/**
 * Output the master inline SVG sprite once in HTML
 */
function render_svg_sprite(): string {
    $icons = get_all_svg_icons();
    $out = '<svg xmlns="http://www.w3.org/2000/svg" style="display: none;" id="__portal_svg_sprite" aria-hidden="true">' . "\n";
    foreach ($icons as $name => $path) {
        $out .= '  <symbol id="icon-' . htmlspecialchars($name, ENT_QUOTES, 'UTF-8') . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' . $path . '</symbol>' . "\n";
    }
    $out .= '</svg>' . "\n";
    return $out;
}

/**
 * Returns an inline SVG using the sprite <use> tag
 */
function svg_icon(string $name, int $size = 20, string $class = ''): string {
    $classAttr = $class ? ' class="svg-icon ' . htmlspecialchars($class, ENT_QUOTES, 'UTF-8') . '"' : ' class="svg-icon"';
    return '<svg width="' . $size . '" height="' . $size . '"' . $classAttr . ' aria-hidden="true"><use href="#icon-' . htmlspecialchars($name, ENT_QUOTES, 'UTF-8') . '"></use></svg>';
}

/**
 * Legacy wrapper: maps to svg_icon
 */
function icon(string $name, string $class = '', int $size = 20): string {
    return svg_icon($name, $size, $class);
}
